//! Guest-side extern declarations and enums of the Wasmicon HAL.
//!
//! @generated by `cargo run -p wasmicon-gen` from `wit/` (wasmicon:hal@0.1.0) and
//! `wit-device/` (wasmicon:device@0.1.0). DO NOT EDIT.
//! Lowering rules: docs/abi-spec.md.

pub mod types {
    /// Error code shared by the whole HAL.
    /// In the Wasmicon ABI a function that returns `result<T, error-code>`
    /// returns a single i32: 0 = success, n > 0 = discriminant + 1.
    #[derive(Clone, Copy, PartialEq, Eq)]
    #[repr(u32)]
    pub enum ErrorCode {
        /// Invalid argument (pin number out of range, zero-length transfer, ...).
        InvalidArgument = 0,
        /// The handle is invalid or has already been dropped.
        InvalidHandle = 1,
        /// The peripheral or pin is already in use.
        Busy = 2,
        /// The operation timed out.
        Timeout = 3,
        /// I2C: the device answered with NACK.
        Nack = 4,
        /// Other I/O error, such as a bus error.
        Io = 5,
        /// The operation or setting is not supported on this platform.
        Unsupported = 6,
        /// The host ran out of resources (for example the handle limit).
        OutOfMemory = 7,
        /// The named item does not exist (an asset that is not in the slot).
        NotFound = 8,
    }

    impl ErrorCode {
        /// Number of cases.
        pub const COUNT: u32 = 9;

        /// Converts from a discriminant. Out of range gives `None` (docs/abi-spec.md §4.1).
        #[must_use]
        pub const fn from_u32(v: u32) -> Option<Self> {
            match v {
                0 => Some(Self::InvalidArgument),
                1 => Some(Self::InvalidHandle),
                2 => Some(Self::Busy),
                3 => Some(Self::Timeout),
                4 => Some(Self::Nack),
                5 => Some(Self::Io),
                6 => Some(Self::Unsupported),
                7 => Some(Self::OutOfMemory),
                8 => Some(Self::NotFound),
                _ => None,
            }
        }

        /// Status value the host returns: discriminant + 1 (docs/abi-spec.md §4.4).
        #[must_use]
        pub const fn status(self) -> u32 {
            self as u32 + 1
        }

        /// Recovers the error code from a status value. 0 (success) and out of range give `None`.
        #[must_use]
        pub const fn from_status(status: u32) -> Option<Self> {
            if status == 0 {
                return None;
            }
            Self::from_u32(status - 1)
        }
    }
}

